code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    vcuts = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]
    hcuts = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    bg = grid[vcuts[0]][vcuts[0]] if vcuts else None
    xstarts = [0] + [c + 1 for c in vcuts]
    xends = vcuts + [w]
    ystarts = [0] + [r + 1 for r in hcuts]
    yends = hcuts + [h]
    out = [row[:] for row in grid]

    def cells(y0, y1, x0, x1, color):
        return {(r-y0, c-x0) for r in range(y0, y1) for c in range(x0, x1)
                if grid[r][c] == color}

    confirmed = set()
    for yi, (y0, y1) in enumerate(zip(ystarts, yends)):
        for xi in range(len(xstarts)-1):
            lx0, lx1 = xstarts[xi], xends[xi]
            rx0, rx1 = xstarts[xi+1], xends[xi+1]
            if lx1-lx0 != rx1-rx0:
                continue
            colors = (set(v for row in grid[y0:y1] for v in row[lx0:lx1]) |
                      set(v for row in grid[y0:y1] for v in row[rx0:rx1])) - {0, bg}
            for color in colors:
                left = cells(y0, y1, lx0, lx1, color)
                right = cells(y0, y1, rx0, rx1, color)
                mirrored = {(r, lx1-lx0-1-c) for r, c in left}
                if left and mirrored == right:
                    confirmed.add((xi, color))

    for xi, color in confirmed:
        lx0, lx1 = xstarts[xi], xends[xi]
        rx0, rx1 = xstarts[xi+1], xends[xi+1]
        width = lx1-lx0
        for y0, y1 in zip(ystarts, yends):
            left = cells(y0, y1, lx0, lx1, color)
            right = cells(y0, y1, rx0, rx1, color)
            for r, c in left:
                out[y0+r][rx0+width-1-c] = color
            for r, c in right:
                out[y0+r][lx0+width-1-c] = color
    return out
'''
